function initialize_interface_enhancements(execute_script) {
	//  Convenience routines
	function obtain_connection_protocol() {
		//  Determines if the current page uses HTTPS or HTTP.
		return "https:" == document.location.protocol ? "https" : "http";
	}

	function add_to_document_head(dom_element) {
		//  Appends a given DOM element to the document's <head> section.
		document.getElementsByTagName("head")[0].appendChild(dom_element);
	}

	function inject_custom_styles() {
		//  Inserts a block of custom CSS into the document's head for styling.
		var style_node = document.createElement("style");
		style_node.type = "text/css";
		if (style_node.styleSheet) style_node.styleSheet.cssText = style_bundle_content;
		else style_node.appendChild(document.createTextNode(style_bundle_content));
		add_to_document_head(style_node);
	}

	//  Integrate typefaces from Google. Powered by Google Web Fonts
	/*
	function load_external_typefaces()
	{
		//  Generate a script element to transmit configuration to Google's service
		var script_node = document.createElement("script");
		script_node.type = "text/javascript";
		script_node.textContent = embedded_font_cfg;
		add_to_document_head(script_node);

		//  Asynchronously load Google's font script
		var script_node = document.createElement("script");
		script_node.type = "text/javascript";
		script_node.src = obtain_connection_protocol() + "://ajax.googleapis.com/ajax/libs/webfont/1/webfont.js";
		script_node.async = "true";
		add_to_document_head(script_node);
	}*/

	//  Retrieve jQuery from Google's content delivery network
	function fetch_jquery_library(execution_callback) {
		//  Prevent redundant loading
		if (typeof jquery_global != 'undefined' && jquery_global) {
			var script_node = document.createElement("script");
			script_node.type = "text/javascript";
			script_node.textContent = "(" + execution_callback.toString() + ")()";
			document.body.appendChild(script_node);
			return;
		}
		//  Initiate jQuery download
		var script_node = document.createElement("script");
		script_node.type = "text/javascript";
		script_node.src = obtain_connection_protocol() + "://ajax.googleapis.com/ajax/libs/jquery/1.9.0/jquery.min.js";
		script_node.addEventListener("load", function() {
			var script_node = document.createElement("script");
			script_node.type = "text/javascript";
			script_node.textContent = "(" + execution_callback.toString() + ")()";
			document.body.appendChild(script_node);
		}, false);
		add_to_document_head(script_node);
	}

	//  load_external_typefaces(); //  We'll utilize embedded fonts for improved performance
	inject_custom_styles();
	fetch_jquery_library(execute_script);
}

